CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, user_name TEXT NOT NULL, active INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resources (id INTEGER PRIMARY KEY AUTOINCREMENT, resource_name TEXT NOT NULL, active INTEGER NOT NULL, capacity INTEGER NOT NULL, custom_field TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, resource_id INTEGER NOT NULL, start INTEGER NOT NULL, end INTEGER NOT NULL, description TEXT, passhash TEXT, created_at INTEGER NOT NULL);
